pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposit0, uint256 deposit1, uint256 collectAmt) public {
        // Bound amounts to avoid overflow/revert on zero/MinSum issues and keep the domain wide
        deposit0 = bound(deposit0, 1, 10 ether);
        deposit1 = bound(deposit1, 1, 10 ether);
        // Ensure collect amount is > 0 and <= deposit0 so deposit0 actor can successfully collect
        vm.assume(collectAmt > 0 && collectAmt <= deposit0);

        address actor0 = address(0x1000);
        address actor1 = address(0x2000);

        // Initialize contract
        c.SetMinSum(0);
        c.Initialized();

        // Deposit from actor0
        vm.deal(actor0, deposit0);
        vm.prank(actor0);
        c.Deposit{value: deposit0}();

        // Deposit from actor1
        vm.deal(actor1, deposit1);
        vm.prank(actor1);
        c.Deposit{value: deposit1}();

        uint256 totalDeposited = deposit0 + deposit1;

        // Actor0 collects
        vm.prank(actor0);
        try c.Collect(collectAmt) {} catch {}

        uint256 bal0 = c.balances(actor0);
        uint256 bal1 = c.balances(actor1);

        // The sum of all balances plus collected amount must equal total deposited
        // Because actor0 collected collectAmt, the remaining sum in c.balances should be totalDeposited - collectAmt
        // Buggy version overwrites balance on deposit, breaking this invariant.
        assertTrue(
            c.balances(actor0) + c.balances(actor1) + collectAmt == totalDeposited
        );
    }
}

