contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amt1, uint256 amt2, uint256 collectAmt, address depositor1, address depositor2) public {
        // Assume distinct addresses and non-zero deposits
        vm.assume(depositor1 != depositor2);
        vm.assume(depositor1 != address(c) && depositor2 != address(c));
        vm.assume(depositor1 != address(0) && depositor2 != address(0));

        // Use bound to keep amounts in a wide but safe range to avoid overflow in the require check
        amt1 = bound(amt1, 1, type(uint128).max);
        amt2 = bound(amt2, 1, type(uint128).max);

        // Initialize the contract so MinSum can be set if needed for collect
        c.Initialized();
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));

        // Depositor 1 deposits amt1
        vm.deal(depositor1, amt1);
        vm.prank(depositor1);
        c.Deposit{value: amt1}();

        // Depositor 2 deposits amt2
        vm.deal(depositor2, amt2);
        vm.prank(depositor2);
        c.Deposit{value: amt2}();

        // Now depositor2 collects an amount not exceeding their own deposit
        collectAmt = bound(collectAmt, 1, amt2);

        vm.prank(depositor2);
        c.Collect(collectAmt);

        // Invariant: Balance of depositor1 must equal their own deposit amt1.
        // Bug: the second deposit overwrites depositor2's balance and does NOT affect depositor1's,
        // but the overwrite on depositor2's deposit is not the issue for depositor1.
        // Actually the correct invariant after two deposits and a collect by depositor2 is:
        // depositor1's balance == amt1 (unchanged). The bug sets depositor2's second deposit
        // to msg.value (overwrites), but depositor1's balance is unaffected.
        // However the bug is in Deposit: balances[msg.sender] = msg.value (overwrite).
        // If depositor1 deposits first, then depositor2 deposits, depositor1's balance should be amt1.
        // In the buggy Deposit, depositor2's deposit overwrites depositor2's balance, not depositor1's.
        // So we need a scenario where the overwrite affects a balance that should be accumulated.
        // We can make depositor1 deposit twice: first deposit amt1, second deposit amt2.
        // Then collect by depositor1: their final balance should be amt1 + amt2 - collectAmt.
        // But the bug overwrites on second deposit, so balance becomes amt2 only, then collectAmt subtracted.
        // That yields an incorrect balance.

        // So we refine: same depositor deposits twice with different amounts, then collects.
    }
}

