pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount) public {
        // sender must be a non-zero EOA, amount > 0
        vm.assume(sender != address(0));
        vm.assume(amount > 0);
        // restrict to amounts that do NOT overflow the sender's balance alone,
        // but where the UPDATE (balance + amount) WOULD overflow.
        // Keep domain wide: fuzz any amount such that type(uint256).max - c.balances(sender) < amount <= type(uint256).max - c.balances(sender) + something reasonable.
        // Actually, any amount > type(uint256).max - c.balances(sender) and <= type(uint256).max is candidate.
        uint256 preBal = c.balances(sender);
        // we need preBal + amount to overflow, but preBal itself does not overflow (it's in [0, type(uint256).max])
        vm.assume(amount > type(uint256).max - preBal);
        // also preBal + amount must be > preBal under normal arithmetic (true if amount>0 and preBal+amount>MAX)

        vm.deal(sender, amount);
        vm.prank(sender);
        // capture revert
        bool ok;
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }
        uint256 postBal = c.balances(sender);

        // General rule: if the Deposit succeeds (reference would revert on overflow),
        // then the resulting balance must NOT be equal to preBal + amount (which wraps).
        // More precisely, the reference NEVER succeeds for overflow inputs; the buggy version may succeed
        // and then postBal = (preBal + amount) mod 2^256, which is < amount (since preBal+amount > MAX and MAX < 2^256).
        // So we need: it is NOT the case that (ok && postBal < amount).
        // But reference passes because ok is always false for these inputs.
        // We assert: !(ok && postBal < amount) – which holds for reference (never ok) but fails for bug.
        assertTrue(!(ok && postBal < amount));
    }
}

